<?php
namespace App\Http\Controllers\Admin\Academics;
use App\Models\Academics\Chapter;use Illuminate\Http\Request;use Illuminate\Support\Facades\DB;use Illuminate\View\View;
class ChapterController extends BaseAcademicsController{private function subjects($id){return DB::table('subjects')->join('subject_group_subjects','subject_group_subjects.subject_id','=','subjects.id')->join('subject_groups','subject_groups.id','=','subject_group_subjects.subject_group_id')->where('subject_groups.class_id',$id)->select('subjects.*')->distinct()->orderBy('subjects.name')->get();}public function index(Request $r):View{$classes=DB::table('classes')->orderBy('id')->get();$chapter=$r->integer('edit')?Chapter::findOrFail($r->integer('edit')):null;$selectedClass=$r->integer('class_id')?:($chapter?->class_id);$subjects=$selectedClass?$this->subjects($selectedClass):collect();$classNames=$classes->pluck('class','id');$records=Chapter::with('subject')->when($r->filled('search'),fn($q)=>$q->where('name','like','%'.$r->string('search').'%')->orWhere('urdu','like','%'.$r->string('search').'%'))->orderBy('id')->paginate(20)->withQueryString();return view('admin.academics.curriculum.chapters',compact('classes','subjects','selectedClass','classNames','records','chapter'));}public function store(Request $r){$d=$r->validate(['class_id'=>'required|exists:classes,id','subject_id'=>'required|exists:subjects,id','eng_name'=>'required|array','eng_name.*'=>'required|string','urdu_name'=>'nullable|array']);foreach($d['eng_name'] as $i=>$n)Chapter::create(['class_id'=>$d['class_id'],'subject_id'=>$d['subject_id'],'name'=>$n,'urdu'=>$d['urdu_name'][$i]??'','is_active'=>'yes']);return back()->with('success','Chapter added successfully.');}public function update(Request $r,Chapter $chapter){$d=$r->validate(['class_id'=>'required|exists:classes,id','subject_id'=>'required|exists:subjects,id','eng_name.0'=>'required|string','urdu_name.0'=>'nullable|string']);$chapter->update(['class_id'=>$d['class_id'],'subject_id'=>$d['subject_id'],'name'=>$d['eng_name'][0],'urdu'=>$d['urdu_name'][0]??'']);return back()->with('success','Chapter updated successfully.');}public function destroy(Chapter $chapter){$chapter->delete();return back()->with('success','Chapter deleted successfully.');}}
